head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


/**
 * @method
 * @name fn_PrintPreView_DB
 * @description desc
 * @param {string} _rexName desc
 * @param {string} _dataType desc
 * @param {string} _dataLocation desc
 * @param {string} _dataXPath desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_PrintPreView_DB = function(_rexName, _dataType, _dataLocation, _dataXPath) {
    // 필수 - rexpert선언 
    var oRptMainParam = rex_GetgoDictionay();
    oRptMainParam.put("rex_rptname", _rexName);
    oRptMainParam.put("rex_datatype", _dataType);
    oRptMainParam.put("rex_data", "http://" + location.host + _dataLocation);
    oRptMainParam.put("rex_xpath", _dataXPath);

    // 옵션 - 팝업설정
    var rex_gsPreViewFeaturesModalCustom = "center:yes;resizable__no;scroll:no;status:no;dialogWidth:725px;dialogHeight:768px";
    oRptMainParam.put("rex_open_window", rex_gsPreViewFeaturesModalCustom);

    // preview 팝업 열기
    rex_gfRexRptOpen("popup", oRptMainParam);
};


//수수료계산
/**
 * @method
 * @name fn_PrintPreView
 * @description desc
 * @param {string} _rexName desc
 * @param {string} _dataType desc
 * @param {string} _formName desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_PrintPreView = function(_rexName, _dataType, _formName) {
    // 필수 - rexpert선언 
    var oRptMainParam = rex_GetgoDictionay();
    oRptMainParam.put("rex_rptname", _rexName);
    oRptMainParam.put("rex_datatype", _dataType);

    // 옵션 - 파라미터 정의
    oRptMainParam.put("reqDivCd", _formName.reqDivCd.getValue());
    oRptMainParam.put("isurCd", _formName.isurCd.getValue());
    oRptMainParam.put("isurNm", _formName.isurNm.getValue());
    oRptMainParam.put("currIsoCd", _formName.currIsoCd.getValue());
    oRptMainParam.put("listAmt", _formName.listAmt.getValue());
    oRptMainParam.put("currUnit", _formName.currUnit.getValue());
    oRptMainParam.put("isuDd", _formName.isuDd.getValue());
    oRptMainParam.put("listDd", _formName.listDd.getValue());
    oRptMainParam.put("redmptDd", _formName.redmptDd.getValue());
    oRptMainParam.put("listFee", _formName.listFee.getValue());
    oRptMainParam.put("listDutyRsn", _formName.listDutyRsn.getValue());
    oRptMainParam.put("anulfee", _formName.anulfee.getValue());
    oRptMainParam.put("anulDutyRsn", _formName.anulDutyRsn.getValue());

    // 옵션 - 팝업설정
    var rex_gsPreViewFeaturesModalCustom = "center:yes;resizable__no;scroll:no;status:no;dialogWidth:825px;dialogHeight:768px";
    oRptMainParam.put("rex_open_window", rex_gsPreViewFeaturesModalCustom);

    // preview 팝업 열기
    rex_gfRexRptOpen("popup", oRptMainParam);
};


