    oRptMainParam.put("apct_nm1", _formName.apct_nm1.getValue());
    oRptMainParam.put("apct_tel_no", _formName.apct_tel_no.getValue());
    oRptMainParam.put("encryp_apct_email", _formName.encryp_apct_email.getValue());
